            return Collections.emptyList();
        }
        if (n == 0) {
            throw new IllegalArgumentException();
        }

        List<Integer> result = new ArrayList<>();
        while (n % p == 0) {
            result.add(p);
            n /= p;
        }
        return result.isEmpty()? factorize(n, ++p) : result;
    }
